01_nba_scoreboard_to_table.mjs:
// 01 — NBA scoreboard → a tidy games table.
//
// Shows: the one pattern to learn, `{ parsed: true }`. The raw ESPN scoreboard
// nests each game under events[].competitions[0].competitors[]; the parsed call
// gives one flat row per game (home_*/away_* columns), ready for a table.
//
// Sources: ESPN Site API v2 — site.api.espn.com/apis/site/v2/sports/basketball/nba/scoreboard
// Offline fixture: test/fixtures/espn/scoreboard_nba.json (SDV_LIVE=1 for today's board).

import sdv from 'sportsdataverse';
import { setup } from './_offline.mjs';
import { printTable } from './_util.mjs';

setup();

// Raw: the provider's exact payload.
const raw = await sdv.nba.espnNbaScoreboard({});
console.log(`raw payload: ${raw.events.length} events, top-level keys = ${Object.keys(raw).join(', ')}`);

// Parsed: one row per game, snake_case, flat.
const games = await sdv.nba.espnNbaScoreboard({ parsed: true });
printTable(
  games,
  ['game_id', 'short_name', 'status_type_detail', 'home_abbreviation', 'home_score', 'away_abbreviation', 'away_score'],
  10,
  'Games (parsed scoreboard)'
);

// A derived table: margin of victory for finished games, biggest first.
const finals = games
  .filter((g) => g.status_type_completed)
  .map((g) => ({
    short_name: g.short_name,
    winner: Number(g.home_score) > Number(g.away_score) ? g.home_abbreviation : g.away_abbreviation,
    margin: Math.abs(Number(g.home_score) - Number(g.away_score)),
    venue: g.venue_full_name,
  }))
  .sort((a, b) => b.margin - a.margin);
printTable(finals, ['short_name', 'winner', 'margin', 'venue'], 5, 'Biggest margins');

02_nba_pbp_shots.mjs:
// 02 — NBA play-by-play → shots with court coordinates.
//
// Shows: the `summary` dispatcher's `plays` sub-frame, and how ESPN encodes shot
// location. The frame below was FITTED on four ESPN basketball captures (NBA
// 401585607, 401430219, 401360428; WNBA 400927398; only the first is committed,
// as test/fixtures/espn/summary_nba.json) by placing the hoop where it best
// reproduces the "N-foot" distance ESPN writes into each play's text (MAE 0.3 ft,
// integer coordinates). test/examples-shot-frame.test.js asserts it on the
// committed capture:
//
//   - coordinate_x: feet ACROSS the court, 0..50; the hoop is at x = 25.
//   - coordinate_y: feet from the HOOP toward half court, -1..~31; the hoop fits
//     at y = 1 on the committed capture (0–1 across the four; not the baseline,
//     which would put it at 5.25). A "23-foot three" from the corner sits at
//     (2, 2); a layup at (25, 2).
//   - BOTH teams are normalised onto the same basket in every period — there is
//     no per-period side flip to undo.
//   - Free throws carry the ESPN "unknown" sentinel (-214748340, -214748365);
//     drop any coordinate < -100 before plotting.
//
// Sources: ESPN Site API v2 — site.api.espn.com/apis/site/v2/sports/basketball/nba/summary?event=…
// Offline fixture: test/fixtures/espn/summary_nba.json (ORL vs TOR, 2024-03-17).

import sdv from 'sportsdataverse';
import { setup } from './_offline.mjs';
import { printTable, round } from './_util.mjs';

setup();

const EVENT_ID = 401585607;
const HOOP = { x: 25, y: 1 }; // the fitted position (MAE 0.32 ft on this capture)

const plays = await sdv.nba.espnNbaSummary({ event_id: EVENT_ID, parsed: true, section: 'plays' });
console.log(`${plays.length} plays in the summary`);

const shots = plays
  .filter((p) => p.shooting_play && p.coordinate_x > -100 && !/free throw/i.test(p.text))
  .map((p) => ({
    period: p.period_number,
    clock: p.clock_display_value,
    team_id: p.team_id,
    made: p.scoring_play,
    pts: p.points_attempted,
    x: p.coordinate_x,
    y: p.coordinate_y,
    dist_ft: round(Math.hypot(p.coordinate_x - HOOP.x, p.coordinate_y - HOOP.y), 1),
    text: p.text,
  }));

printTable(shots, ['period', 'clock', 'team_id', 'made', 'pts', 'x', 'y', 'dist_ft', 'text'], 8, 'Field-goal attempts with coordinates');

// Sanity check of the convention: threes should be ≥ ~22 ft from the hoop, rim
// attempts (dunks / layups / tips) within a few feet.
const bucket = (label, pred) => {
  const d = shots.filter(pred).map((s) => s.dist_ft).sort((a, b) => a - b);
  return { shot_type: label, n: d.length, min_ft: d[0], median_ft: d[d.length >> 1], max_ft: d[d.length - 1] };
};
printTable(
  [
    bucket('three (points_attempted = 3)', (s) => s.pts === 3),
    bucket('rim (dunk / layup / tip)', (s) => /dunk|layup|tip/i.test(s.text)),
    bucket('other two', (s) => s.pts === 2 && !/dunk|layup|tip/i.test(s.text)),
  ],
  ['shot_type', 'n', 'min_ft', 'median_ft', 'max_ft'],
  3,
  'Distance from the hoop at (25, 0), by shot type'
);

03_wnba_standings.mjs:
// 03 — WNBA standings → conference tables.
//
// Shows: the ESPN `standings` endpoint parsed to one row per team, grouped by
// conference, plus a derived Pythagorean-expectation column. The same call works
// on every league namespace (sdv.nba / sdv.nfl / sdv.nhl / … .espn<Lg>Standings).
//
// Sources: ESPN Site API v2 — site.api.espn.com/apis/v2/sports/basketball/wnba/standings?season=2025
// Offline fixture: test/fixtures/espn/standings_wnba_2025.json (captured 2026-10-06).

import sdv from 'sportsdataverse';
import { setup } from './_offline.mjs';
import { printTable, round } from './_util.mjs';

setup();

const rows = await sdv.wnba.espnWnbaStandings({ season: 2025, parsed: true });
console.log(`${rows.length} teams across ${new Set(rows.map((r) => r.group_name)).size} groups`);

const table = rows.map((r) => {
  const pf = r.points_for;
  const pa = r.points_against;
  return {
    conf: r.group_abbreviation,
    team: r.team_abbreviation,
    w: r.wins,
    l: r.losses,
    win_pct: round(r.win_percent, 3),
    diff: round(r.differential, 1),
    pyth: round(pf ** 13.91 / (pf ** 13.91 + pa ** 13.91), 3), // basketball exponent
    streak: r.streak,
    seed: r.playoff_seed,
  };
});

for (const conf of ['E', 'W']) {
  printTable(
    table.filter((t) => t.conf === conf).sort((a, b) => b.win_pct - a.win_pct),
    ['team', 'w', 'l', 'win_pct', 'diff', 'pyth', 'streak', 'seed'],
    8,
    `${conf === 'E' ? 'Eastern' : 'Western'} Conference`
  );
}

04_nfl_schedule_and_standings.mjs:
// 04 — NFL week-1 schedule + season standings, joined on team_id.
//
// Shows: two ESPN calls on the same namespace and a join on the string
// `team_id` that both parsers emit (ids are ALWAYS decimal strings in v4, so a
// Map keyed by id works across endpoints).
//
// Sources: ESPN Site API v2 —
//   site.api.espn.com/apis/site/v2/sports/football/nfl/scoreboard?dates=2024&week=1&seasontype=2
//   site.api.espn.com/apis/v2/sports/football/nfl/standings?season=2024
// Offline fixtures: test/fixtures/espn/scoreboard_nfl_2024_w1.json, standings_nfl_2024.json
// (both captured 2026-10-06).

import sdv from 'sportsdataverse';
import { setup } from './_offline.mjs';
import { printTable, round } from './_util.mjs';

setup();

const games = await sdv.nfl.espnNflScoreboard({ dates: 2024, week: 1, season_type: 2, parsed: true });
const standings = await sdv.nfl.espnNflStandings({ season: 2024, parsed: true });
console.log(`${games.length} week-1 games; ${standings.length} teams in the standings`);

printTable(
  games,
  ['game_id', 'date', 'short_name', 'home_score', 'away_score', 'venue_full_name'],
  6,
  'Week 1, 2024 (parsed scoreboard)'
);

// Join: final-season record for both teams of each week-1 game.
const byId = new Map(standings.map((s) => [s.team_id, s]));
const joined = games.map((g) => {
  const h = byId.get(g.home_id);
  const a = byId.get(g.away_id);
  return {
    short_name: g.short_name,
    home_final: h ? `${h.wins}-${h.losses}${h.ties ? `-${h.ties}` : ''}` : '',
    away_final: a ? `${a.wins}-${a.losses}${a.ties ? `-${a.ties}` : ''}` : '',
    home_seed: h?.playoff_seed || '',
    away_seed: a?.playoff_seed || '',
  };
});
printTable(joined, ['short_name', 'home_final', 'away_final', 'home_seed', 'away_seed'], 6, 'Week-1 matchups with end-of-season records');

// Division table from the standings frame.
printTable(
  standings
    .filter((s) => s.group_abbreviation === 'AFC')
    .sort((a, b) => b.win_percent - a.win_percent)
    .map((s) => ({ team: s.team_abbreviation, w: s.wins, l: s.losses, pct: round(s.win_percent, 3), pf: s.points_for, pa: s.points_against, diff: s.point_differential })),
  ['team', 'w', 'l', 'pct', 'pf', 'pa', 'diff'],
  8,
  'AFC by win percentage'
);

05_cfb_rankings_and_pbp.mjs:
// 05 — College football: AP poll + one game's drives and scoring plays.
//
// Shows: the ESPN CDN family (cdn.espn.com/core, the pages espn.com itself
// renders): `cdn_rankings` gives one row per poll entry across every poll, and
// `cdn_playbyplay` is a sectioned dispatcher like `summary` — football ships
// drives[] + scoringPlays[] instead of flat plays[], so ask for `drives`,
// `drive_plays` (plays unrolled with drive_id / drive_sequence) or `scoring_plays`.
//
// Sources: ESPN CDN — cdn.espn.com/core/college-football/rankings?xhr=1&week=5
//                     cdn.espn.com/core/college-football/playbyplay?xhr=1&gameId=401628551
// Offline fixtures: test/fixtures/espn/cdn/rankings_cfb.json.gz, playbyplay_cfb.json.gz
// (sdv-py captures, 2024 week 5 / Wisconsin at Oregon 2024-11-16).

import sdv from 'sportsdataverse';
import { setup } from './_offline.mjs';
import { printTable } from './_util.mjs';

setup();

const polls = await sdv.cfb.espnCfbCdnRankings({ week: 5, parsed: true });
console.log(`${polls.length} poll entries across polls: ${[...new Set(polls.map((p) => p.poll_name))].join(' | ')}`);
printTable(
  polls.filter((p) => p.poll_name === 'AP Top 25'),
  ['rank', 'team_abbreviation', 'team_display_name', 'formatted_record', 'points', 'first_place_votes', 'trend'],
  10,
  'AP Top 25'
);

const GAME_ID = 401628551;
const drives = await sdv.cfb.espnCfbCdnPlaybyplay({ game_id: GAME_ID, parsed: true, section: 'drives' });
const scoring = await sdv.cfb.espnCfbCdnPlaybyplay({ game_id: GAME_ID, parsed: true, section: 'scoring_plays' });
const plays = await sdv.cfb.espnCfbCdnPlaybyplay({ game_id: GAME_ID, parsed: true, section: 'drive_plays' });
console.log(`${drives.length} drives, ${plays.length} plays, ${scoring.length} scoring plays`);

printTable(
  drives.map((d) => ({
    seq: d.id.slice(-2),
    offense: d.team_abbreviation,
    start: d.start_text,
    plays: d.offensive_plays,
    yards: d.yards,
    time: d.time_elapsed_display_value,
    result: d.display_result,
  })),
  ['seq', 'offense', 'start', 'plays', 'yards', 'time', 'result'],
  8,
  'Drives'
);

printTable(
  scoring.map((s) => ({ q: s.period_number, clock: s.clock_display_value, team: s.team_abbreviation, type: s.scoring_type_abbreviation, score: `${s.away_score}-${s.home_score}`, text: s.text.trim() })),
  ['q', 'clock', 'team', 'type', 'score', 'text'],
  8,
  'Scoring plays'
);

06_college_basketball_torvik_and_espn.mj:
// 06 — Men's college basketball: BartTorvik ratings + an ESPN box score.
//
// Shows: a non-ESPN provider on the same `{ parsed: true }` contract. BartTorvik
// serves CSV (with a header for team results) behind a browser-UA check — the
// `torvik` runtime handles both, so the wrapper returns rows like any other. Then
// the ESPN `summary` dispatcher's `boxscore_player` / `boxscore_team` sub-frames
// for one game (team stats are long-form: one row per team × stat).
//
// Sources: BartTorvik — barttorvik.com/2024_team_results.csv
//          ESPN Site API v2 — site.api.espn.com/apis/site/v2/sports/basketball/mens-college-basketball/summary?event=401600379
// Offline fixtures: test/fixtures/torvik/torvik_ratings.csv (2026-06-18, 3 rows),
//                   test/fixtures/espn/basketball_pbp/mbb_summary_401600379.json.gz (Maryland at Illinois, 2024-02-10).

import sdv from 'sportsdataverse';
import { setup } from './_offline.mjs';
import { printTable, round } from './_util.mjs';

setup();

const ratings = await sdv.torvik.torvikRatings({ year: 2024, parsed: true });
printTable(
  ratings.map((r) => ({
    rank: Number(r.rank),
    team: r.team,
    conf: r.conf,
    record: r.record,
    adj_oe: round(Number(r.adjoe), 1),
    adj_de: round(Number(r.adjde), 1),
    barthag: round(Number(r.barthag), 3),
    adj_t: round(Number(r.adjt), 1),
  })),
  ['rank', 'team', 'conf', 'record', 'adj_oe', 'adj_de', 'barthag', 'adj_t'],
  5,
  'T-Rank 2023-24 (torvik_ratings)'
);

const EVENT_ID = 401600379;
const players = await sdv.mbb.espnMbbSummary({ event_id: EVENT_ID, parsed: true, section: 'boxscore_player' });
const teams = await sdv.mbb.espnMbbSummary({ event_id: EVENT_ID, parsed: true, section: 'boxscore_team' });
console.log(`${players.length} player rows, ${teams.length} team-stat rows`);

printTable(
  players
    .filter((p) => !p.did_not_play)
    .map((p) => ({ team: p.team_abbreviation, player: p.athlete_short_name, pos: p.athlete_position, min: Number(p.minutes), pts: Number(p.points), fg: p.field_goals_made_field_goals_attempted, reb: Number(p.rebounds), ast: Number(p.assists) }))
    .sort((a, b) => b.pts - a.pts),
  ['team', 'player', 'pos', 'min', 'pts', 'fg', 'reb', 'ast'],
  8,
  'Top scorers (boxscore_player)'
);

// Pivot the long team frame to one row per stat with a column per team.
const abbrs = [...new Set(teams.map((t) => t.team_abbreviation))];
const byStat = new Map();
for (const t of teams) {
  if (!byStat.has(t.stat_label)) byStat.set(t.stat_label, { stat: t.stat_label });
  byStat.get(t.stat_label)[t.team_abbreviation] = t.stat_display_value;
}
printTable([...byStat.values()], ['stat', ...abbrs], 8, 'Team totals (boxscore_team, pivoted)');

07_mlb_statcast_and_stats_api.mjs:
// 07 — MLB: a Baseball Savant leaderboard + the Stats API for one game.
//
// Shows: two MLB sources with different wire formats behind one contract. Savant
// leaderboards are CSV (the `mlb_statcast` runtime asks for csv=true and parses
// it); the Stats API is JSON. `mlbLinescore` gives one row per inning and
// `mlbBoxscore` one row per player with `stats_batting_*` / `stats_pitching_*`.
//
// Sources: Baseball Savant — baseballsavant.mlb.com/leaderboard/catcher-stance?csv=true
//          MLB Stats API — statsapi.mlb.com/api/v1/game/745282/linescore, …/boxscore
// Offline fixtures: test/fixtures/py/mlb_statcast/leaderboard_catcher_stance.csv,
//                   test/fixtures/py/mlb/linescore_745282.json, boxscore_745282.json.gz
// (sdv-py captures; game 745282 = Cardinals at Giants, 2024).

import sdv from 'sportsdataverse';
import { setup } from './_offline.mjs';
import { printTable, round } from './_util.mjs';

setup();

const stance = await sdv.mlb.mlbStatcastLeaderboardCatcherStance({ parsed: true });
printTable(
  stance.map((r) => ({
    name: r.name,
    year: r.year,
    pitches: r.pitches,
    knee_down_pct: round(r.knee_down_pct, 3),
    one_knee_framing_rv: round(r.one_knee_framing_rv, 1),
    other_framing_rv: round(r.other_framing_rv, 1),
    catching_rv: round(r.catching_rv, 1),
  })),
  ['name', 'year', 'pitches', 'knee_down_pct', 'one_knee_framing_rv', 'other_framing_rv', 'catching_rv'],
  7,
  'Statcast catcher-stance leaderboard (CSV → rows)'
);

const GAME_PK = 745282;
const line = await sdv.mlb.mlbLinescore({ game_pk: GAME_PK, parsed: true });
printTable(line, ['ordinal_num', 'away_runs', 'away_hits', 'away_errors', 'home_runs', 'home_hits', 'home_errors'], 9, `Linescore, game ${GAME_PK}`);

const box = await sdv.mlb.mlbBoxscore({ game_pk: GAME_PK, parsed: true });
const batters = box
  .filter((p) => p.batting_order)
  .map((p) => ({
    side: p.team_side,
    order: p.batting_order,
    player: p.person_boxscore_name,
    pos: p.position_abbreviation,
    ab: p.stats_batting_at_bats,
    h: p.stats_batting_hits,
    hr: p.stats_batting_home_runs,
    rbi: p.stats_batting_rbi,
    bb: p.stats_batting_base_on_balls,
    k: p.stats_batting_strike_outs,
  }))
  .sort((a, b) => a.side.localeCompare(b.side) || Number(a.order) - Number(b.order));
printTable(batters, ['side', 'order', 'player', 'pos', 'ab', 'h', 'hr', 'rbi', 'bb', 'k'], 9, 'Starting lineups (boxscore rows with a batting order)');

08_nhl_api_web_and_edge.mjs:
// 08 — NHL: api-web standings + a game's play-by-play, and an EDGE leaderboard.
//
// Shows: the three NHL families on sdv.nhl — `nhl*` (api-web.nhle.com/v1, the
// modern game feed), `nhlEdge*` (api-web.nhle.com/v1/edge, player tracking) and
// their py-parity parsers. `nhlWebPbp` returns one row per event; EDGE "landing"
// payloads are one wide row of leaders, so we reshape it into a long table.
//
// Sources: NHL api-web — api-web.nhle.com/v1/standings/now, /v1/gamecenter/2023030417/play-by-play
//          NHL EDGE — api-web.nhle.com/v1/edge/skater-landing/now
// Offline fixtures: test/fixtures/py/nhl_api_web/standings_now.json.gz, pbp_2024_scf_g7.json.gz
//                   (2024 Stanley Cup Final game 7), test/fixtures/py/nhl_edge/skater_landing.json.

import sdv from 'sportsdataverse';
import { setup } from './_offline.mjs';
import { printTable, round } from './_util.mjs';

setup();

const standings = await sdv.nhl.nhlStandings({ parsed: true });
printTable(
  standings
    .sort((a, b) => b.points - a.points)
    .map((s) => ({ team: s.team_abbrev_default, div: s.division_abbrev, gp: s.games_played, w: s.wins, l: s.losses, otl: s.ot_losses, pts: s.points, gd: s.goal_differential, l10: `${s.l10_wins}-${s.l10_losses}-${s.l10_ot_losses}` })),
  ['team', 'div', 'gp', 'w', 'l', 'otl', 'pts', 'gd', 'l10'],
  8,
  'League standings by points'
);

const GAME_ID = 2023030417;
const pbp = await sdv.nhl.nhlWebPbp({ game_id: GAME_ID, parsed: true });
const counts = new Map();
for (const p of pbp) counts.set(p.type_desc_key, (counts.get(p.type_desc_key) ?? 0) + 1);
printTable(
  [...counts].map(([type, n]) => ({ event_type: type, n })).sort((a, b) => b.n - a.n),
  ['event_type', 'n'],
  8,
  `Event mix, game ${GAME_ID} (${pbp.length} events)`
);
printTable(
  pbp.filter((p) => p.type_desc_key === 'goal').map((p) => ({ period: p.period_descriptor_number, time: p.time_in_period, situation: p.situation_code, scorer_id: p.details_scoring_player_id, score: `${p.details_away_score}-${p.details_home_score}`, x: p.details_x_coord, y: p.details_y_coord })),
  ['period', 'time', 'situation', 'scorer_id', 'score', 'x', 'y'],
  8,
  'Goals'
);

// EDGE landing: one wide row → long (leader category, player, value).
const [edge] = await sdv.nhl.nhlEdgeSkaterLanding({ parsed: true });
// Each category is `leaders_<cat>_player_*` + one value key whose name is the
// metric (`..._shot_speed_imperial`, `..._distance_imperial`, …).
const leaders = [];
for (const k of Object.keys(edge)) {
  const m = k.match(/^leaders_(\w+)_player_id$/);
  if (!m) continue;
  const cat = m[1];
  const prefix = `leaders_${cat}_`;
  const valueKey = Object.keys(edge).find((x) => x.startsWith(prefix) && !x.startsWith(`${prefix}player_`) && !x.startsWith(`${prefix}overlay_`));
  leaders.push({
    category: cat,
    player: `${edge[`${prefix}player_first_name_default`]} ${edge[`${prefix}player_last_name_default`]}`,
    team: edge[`${prefix}player_team_abbrev`],
    metric: valueKey?.slice(prefix.length),
    value: round(edge[valueKey], 2),
  });
}
printTable(leaders, ['category', 'player', 'team', 'metric', 'value'], 8, 'EDGE skater leaders (reshaped from the wide landing row)');

09_hockeytech_pwhl_corsi.mjs:
// 09 — PWHL (HockeyTech): play-by-play, time on ice and on-ice Corsi for one game.
//
// Shows: the HockeyTech family's analytics layer. One feed gateway serves 20
// leagues; `sdv.hockeytech.pwhl_*` pins the PWHL. `pwhl_pbp` is the parsed
// gameCenterPlayByPlay (shots carry x_coord / y_coord on the league's canvas),
// `pwhl_player_toi` folds the shift chart into per-player TOI, and
// `pwhl_game_corsi` credits every shot attempt to the skaters on the ice
// (ported from sdv-py's hockeytech `_analytics`). Three feeds, one game id.
//
// Sources: HockeyTech — lscluster.hockeytech.com/feed/index.php
//   feed=statviewfeed&view=gameCenterPlayByPlay, feed=modulekit&view=gameshifts, feed=gc&tab=gamesummary
// Offline fixtures: test/fixtures/hockeytech/analytics/pwhl_{pbp,gameshifts,game_summary}_42.json
// (PWHL game 42, sdv-py analytics oracle captures).

import sdv from 'sportsdataverse';
import { setup } from './_offline.mjs';
import { printTable, round } from './_util.mjs';

setup();

const GAME_ID = 42;

const pbp = await sdv.hockeytech.pwhl_pbp(GAME_ID);
const shots = pbp.filter((p) => p.event === 'shot' || p.event === 'goal');
console.log(`${pbp.length} events, ${shots.length} shots/goals`);
printTable(
  shots.map((p) => ({ period: p.period_of_game, time: p.time_of_period, team_id: p.team_id, shooter: `${p.player_name_first ?? ''} ${p.player_name_last ?? ''}`.trim(), event: p.event, quality: p.shot_quality, x: p.x_coord, y: p.y_coord })),
  ['period', 'time', 'team_id', 'shooter', 'event', 'quality', 'x', 'y'],
  8,
  'Shot attempts (pwhl_pbp)'
);

const toi = await sdv.hockeytech.pwhl_player_toi(GAME_ID);
const corsi = await sdv.hockeytech.pwhl_game_corsi(GAME_ID);
const names = new Map(toi.map((t) => [t.player_id, `${t.first_name} ${t.last_name}`]));

printTable(
  corsi
    .filter((c) => c.toi_seconds >= 600) // skaters with 10+ minutes
    .map((c) => ({
      player: names.get(c.player_id) ?? c.player_id,
      toi: `${Math.floor(c.toi_seconds / 60)}:${String(c.toi_seconds % 60).padStart(2, '0')}`,
      cf: c.corsi_for,
      ca: c.corsi_against,
      cf_pct: round(c.corsi_for_pct, 3),
      ff_pct: round(c.fenwick_for_pct, 3),
      cf_per60: round(c.corsi_for_per60, 1),
    }))
    .sort((a, b) => b.cf_pct - a.cf_pct),
  ['player', 'toi', 'cf', 'ca', 'cf_pct', 'ff_pct', 'cf_per60'],
  10,
  'On-ice Corsi, skaters with 10+ minutes (pwhl_game_corsi + pwhl_player_toi)'
);

10_soccer_cross_league.mjs:
// 10 — Soccer: one namespace, many competitions (the `league` parameter).
//
// Shows: ESPN soccer is league-parameterised — `sdv.soccer.*` takes a `league`
// slug (eng.1, esp.1, ger.1, usa.1, …), and the convenience namespaces
// (`sdv.epl`, `sdv.laliga`, `sdv.bundesliga`, `sdv.mls`, …) pin the slug. The
// same function on `sdv.soccer` with `{ league }` and on `sdv.laliga` without
// it are the same request. Also the ESPN CDN scoreboard, which takes a date.
//
// Sources: ESPN Site API v2 — site.api.espn.com/apis/v2/sports/soccer/esp.1/standings?season=2024
//          ESPN CDN — cdn.espn.com/core/eng.1/scoreboard?xhr=1&date=20250201
// Offline fixtures: test/fixtures/espn/standings_laliga_2024.json (captured 2026-10-06),
//                   test/fixtures/espn/cdn/scoreboard_epl.json.gz (sdv-py capture).

import sdv from 'sportsdataverse';
import { setup } from './_offline.mjs';
import { printTable } from './_util.mjs';

setup();

// The two spellings resolve to the same request.
const viaParam = await sdv.soccer.espnSoccerStandings({ league: 'esp.1', season: 2024, parsed: true });
const viaNamespace = await sdv.laliga.espnLaligaStandings({ season: 2024, parsed: true });
console.log(`sdv.soccer + { league: 'esp.1' } → ${viaParam.length} rows; sdv.laliga → ${viaNamespace.length} rows; same table: ${JSON.stringify(viaParam) === JSON.stringify(viaNamespace)}`);

printTable(
  viaParam
    .sort((a, b) => a.rank - b.rank)
    .map((t) => ({ rank: t.rank, team: t.team_display_name, gp: t.games_played, w: t.wins, d: t.ties, l: t.losses, gf: t.points_for, ga: t.points_against, gd: t.point_differential, pts: t.points })),
  ['rank', 'team', 'gp', 'w', 'd', 'l', 'gf', 'ga', 'gd', 'pts'],
  8,
  'LaLiga 2024-25 (espnSoccerStandings, league = esp.1)'
);

const epl = await sdv.epl.espnEplCdnScoreboard({ date: 20250201, parsed: true });
printTable(
  epl.map((g) => ({ game_id: g.game_id, date: g.date.slice(0, 16), match: g.short_name, status: g.status_type_description, home: g.home_abbreviation, hs: g.home_score, away: g.away_abbreviation, as: g.away_score })),
  ['game_id', 'date', 'match', 'status', 'home', 'hs', 'away', 'as'],
  6,
  'Premier League, 2025-02-01 (espnEplCdnScoreboard)'
);

// Which soccer namespaces exist, and the slug each one pins.
import { LEAGUES } from 'sportsdataverse';
printTable(
  LEAGUES.filter((l) => l.sport === 'soccer').map((l) => ({ namespace: `sdv.${l.prefix}`, slug: l.league, league_param: l.league_param ? 'yes' : '' })),
  ['namespace', 'slug', 'league_param'],
  12,
  'Soccer namespaces (LEAGUES)'
);

11_providers_odds_math.mjs:
// 11 — The Odds API: a historical odds snapshot → de-vigged win probabilities.
//
// Shows: a provider namespace (`sdv.odds.oddsApi*`, caller-supplied api_key)
// whose parsed frame unrolls bookmakers × markets × outcomes into one row per
// outcome, and the market-math helpers merged onto the same namespace
// (`probFromAmerican`, `devigMultiplicative`, `devigShin`, … — a port of sdv-py
// `wexp.market`). The lines are real: a 2020 NFL opener snapshot from the
// SportsDataverse odds-data backfill.
//
// Sources: The Odds API v4 — api.the-odds-api.com/v4/historical/sports/americanfootball_nfl/odds
// Offline fixture: test/fixtures/odds/nfl_lines_20200911T001500Z_0.json
// (sportsdataverse/odds-data `odds/nfl/lines/20200911T001500Z_0.json`, HOU @ KC 2020-09-10).

import sdv from 'sportsdataverse';
import { setup } from './_offline.mjs';
import { printTable, round } from './_util.mjs';

setup();

const rows = await sdv.odds.oddsApiSportsOddsHistory({
  sport_key: 'americanfootball_nfl',
  api_key: process.env.ODDS_API_KEY ?? 'offline',
  date: '2020-09-11T00:15:00Z',
  regions: 'us',
  markets: 'h2h',
  parsed: true,
});
console.log(`${rows.length} outcome rows, snapshot ${rows[0]?.timestamp}, markets: ${[...new Set(rows.map((r) => r.market_key))].join(', ')}`);

const h2h = rows.filter((r) => r.market_key === 'h2h');
printTable(h2h, ['home_team', 'away_team', 'bookmaker', 'outcomes_name', 'outcomes_price'], 6, 'h2h outcomes (one row per bookmaker × outcome)');

// Per bookmaker: raw implied probabilities, the overround, and two de-vig methods.
const byBook = new Map();
for (const r of h2h) {
  if (!byBook.has(r.bookmaker_key)) byBook.set(r.bookmaker_key, []);
  byBook.get(r.bookmaker_key).push(r);
}
const table = [];
for (const [book, outs] of byBook) {
  const home = outs.find((o) => o.outcomes_name === o.home_team);
  const away = outs.find((o) => o.outcomes_name === o.away_team);
  if (!home || !away) continue;
  const raw = [sdv.odds.probFromAmerican(home.outcomes_price), sdv.odds.probFromAmerican(away.outcomes_price)];
  const mult = sdv.odds.devigMultiplicative(raw);
  const shin = sdv.odds.devigShin(raw);
  table.push({
    bookmaker: book,
    home_price: home.outcomes_price,
    away_price: away.outcomes_price,
    overround: round(raw[0] + raw[1] - 1, 4),
    home_raw: round(raw[0], 4),
    home_mult: round(mult[0], 4),
    home_shin: round(shin[0], 4),
  });
}
printTable(table.sort((a, b) => a.overround - b.overround), ['bookmaker', 'home_price', 'away_price', 'overround', 'home_raw', 'home_mult', 'home_shin'], 10, 'Kansas City win probability by bookmaker (raw → de-vigged)');

// The consensus (median of the Shin-de-vigged home probabilities) and a spread
// cross-check. `spreadToProb(spread, sigma)` is Phi(spread / sigma) with `spread`
// the expected HOME margin (KC was a 9.5-point favourite → +9.5), sigma the
// historical NFL margin sd (~13.5).
const med = (a) => { const s = [...a].sort((x, y) => x - y); return s[s.length >> 1]; };
const consensus = med(table.map((t) => t.home_shin));
const fromSpread = sdv.odds.spreadToProb(9.5, 13.5);
printTable(
  [
    { quantity: 'consensus P(home): median Shin', value: round(consensus, 4) },
    { quantity: 'spreadToProb(+9.5, 13.5)', value: round(fromSpread, 4) },
    { quantity: 'logitBlend(consensus, spread, 0.7)', value: round(sdv.odds.logitBlend(consensus, fromSpread, 0.7), 4) },
  ],
  ['quantity', 'value'],
  3,
  'Market math helpers'
);

12_release_loaders.mjs:
// 12 — Release-dataset loaders: parquet assets → rows, with the id rule.
//
// Shows: the generated `load*` loaders (one per sportsdataverse-data /
// nflverse release asset, `tools/codegen/endpoints/releases.yaml`). They stream
// the parquet from GitHub Releases (hyparquet) and apply the v4 integer-id rule:
// a column whose NAME marks an id (`team_id`, `game_id`, `athlete_id`, …) is
// ALWAYS a decimal string, whatever width it was stored with — so
// `cfb_ratings` (stores team_id as a STRING) and `cfb_team_portal` (stores it
// as INT64) join on `===`. Non-id integers are `number`, or `BigInt` past 2^53.
//
// Sources: GitHub Releases — github.com/sportsdataverse/sportsdataverse-data/releases/download/
//   cfb_ratings/cfb_ratings_2024.parquet, cfb_team_portal/cfb_team_portal_2024.parquet, nhl_groups/nhl_groups.parquet
// Offline fixtures: test/fixtures/releases/*.parquet (verbatim release assets, 2026-10-05).

import sdv from 'sportsdataverse';
import { setup } from './_offline.mjs';
import { printTable, round } from './_util.mjs';

setup();

const ratings = await sdv.cfb.loadCfbRatings({ seasons: [2024] });
const portal = await sdv.cfb.loadCfbTeamPortal({ seasons: [2024] });
console.log(`cfb_ratings: ${ratings.length} rows; cfb_team_portal: ${portal.length} rows`);
console.log(`typeof team_id — ratings: ${typeof ratings[0].team_id} (parquet STRING), portal: ${typeof portal[0].team_id} (parquet INT64) → both "${ratings[0].team_id}"-style strings`);

printTable(
  ratings
    .sort((a, b) => a.net_rank - b.net_rank)
    .map((r) => ({ net_rank: r.net_rank, team_id: r.team_id, games: r.games, adj_off_epa: round(r.adj_off_epa, 3), adj_def_epa: round(r.adj_def_epa, 3), adj_net: round(r.adj_net, 3), fei_net: round(r.fei_net, 3) })),
  ['net_rank', 'team_id', 'games', 'adj_off_epa', 'adj_def_epa', 'adj_net', 'fei_net'],
  8,
  'cfb_ratings 2024, top of the net-EPA table'
);

// Join across the two releases on the (string) team_id.
const portalById = new Map(portal.map((p) => [p.team_id, p]));
const joined = ratings
  .map((r) => ({ r, p: portalById.get(r.team_id) }))
  .filter(({ p }) => p)
  .map(({ r, p }) => ({ team_id: r.team_id, net_rank: r.net_rank, roster_n: p.roster_n, transfers_in: p.transfers_in_n, transfers_out: p.transfers_out_n, net_transfer_talent: p.net_transfer_talent, portal_share: round(p.portal_share, 3) }))
  .sort((a, b) => b.net_transfer_talent - a.net_transfer_talent);
console.log(`${joined.length} of ${ratings.length} rated teams matched a portal row (string === string)`);
printTable(joined, ['team_id', 'net_rank', 'roster_n', 'transfers_in', 'transfers_out', 'net_transfer_talent', 'portal_share'], 8, 'Ratings ⋈ transfer portal, by net transfer talent');

// A single-asset loader (no season token).
const groups = await sdv.nhl.loadNhlGroups({});
printTable(groups, ['group_id', 'level', 'first_season', 'last_season'], 8, 'nhl_groups (single-asset loader)');

13_discover_and_utilities.mjs:
// 13 — Discovering the surface: listFunctions, findTeam, and the parser registry.
//
// Shows: the runtime index of what the package exposes. `listFunctions(league)`
// returns the callable names on a namespace (camelCase canonical, with the
// snake_case twins folded away), `functionCount()` the per-namespace totals,
// `findTeam(name, league)` resolves a fuzzy team name to its ESPN team record
// (one `teams` request per league, cached), and the `sportsdataverse/parsers`
// subpath (`parseEndpoint`, `PARSERS`) exposes the parser layer so you can run a
// registered parser on JSON you already have — the same bundle the docs
// playground runs in the browser.
//
// Sources: ESPN Site API v2 — site.api.espn.com/apis/site/v2/sports/basketball/nba/teams (findTeam)
// Offline fixture: test/fixtures/espn/teams_site_nba.json (all 30 teams, 2026-10-05).

import sdv, { listFunctions, functionCount, findTeam, LEAGUES } from 'sportsdataverse';
import { parseEndpoint, PARSERS } from 'sportsdataverse/parsers';
import { readFileSync } from 'node:fs';
import { setup } from './_offline.mjs';
import { printTable } from './_util.mjs';

setup();

// 1. How big is each namespace?
const counts = await functionCount();
printTable(
  Object.entries(counts).map(([ns, n]) => ({ namespace: `sdv.${ns}`, functions: n })).sort((a, b) => b.functions - a.functions),
  ['namespace', 'functions'],
  10,
  'Largest namespaces (functionCount)'
);

// 2. Search within a league.
const nhlShots = await listFunctions('nhl', { search: 'shot' });
printTable(nhlShots.map((name) => ({ name })), ['name'], 10, `sdv.nhl functions matching "shot" (${nhlShots.length})`);

// 3. Resolve a team by (partial) name → ESPN team record.
const team = await findTeam('Celtics', 'nba');
printTable([{ id: team.id, abbreviation: team.abbreviation, displayName: team.displayName, color: team.color, slug: team.slug }], ['id', 'abbreviation', 'displayName', 'color', 'slug'], 1, "findTeam('Celtics', 'nba')");

// 4. The parser registry: run a registered parser on a payload you already hold.
const raw = JSON.parse(readFileSync(new URL('../test/fixtures/espn/scoreboard_nba.json', import.meta.url), 'utf8'));
const rows = parseEndpoint('espn', 'scoreboard', raw);
console.log(`PARSERS: ${Object.keys(PARSERS).length} flat parsers registered; parseEndpoint('espn', 'scoreboard', raw) → ${rows.length} rows, ${Object.keys(rows[0]).length} columns`);
printTable(rows, ['game_id', 'short_name', 'status_type_description', 'home_score', 'away_score'], 4, 'parseEndpoint("espn", "scoreboard", raw) on a saved payload');

// 5. The league matrix.
printTable(
  LEAGUES.map((l) => ({ prefix: l.prefix, sport: l.sport, league: l.league, scopes: l.scopes.join('+') })),
  ['prefix', 'sport', 'league', 'scopes'],
  8,
  `LEAGUES (${LEAGUES.length} entries)`
);

90_sdvplot_shot_chart.mjs:
// 90 — Shot chart: ESPN NBA plays → a sporty court → SVG with sdvplot team colours.
//
// Shows: ESPN summary `plays` (coordinate_x / coordinate_y) mapped onto a
// @sportsdataverse/sporty NBA half court and rendered with `toSVG`, with each
// team's shots coloured by @sportsdataverse/sdvplot `teamColors`. Written to
// examples/out/shot_chart.svg. Both packages are UNPUBLISHED (see README.md).
//
// Coordinate mapping (fitted, not assumed — see 02_nba_pbp_shots.mjs and
// test/examples-shot-frame.test.js): fitting the hoop against the "N-foot"
// distance in each play's text on four ESPN basketball captures (one committed)
// gives hoop = (25, 1) with MAE 0.3 ft, so ESPN's frame is
//   x: feet across the court, 0..50, hoop at 25
//   y: feet from the hoop toward half court, -1..~31 (hoop at y = 1)
//   both teams on ONE basket in every period (no side flip)
//   free throws = sentinel (-214748340, -214748365) → dropped
// sporty's NBA court is centre-origin feet: x along the length (-47..47), y across
// (-25..25); `displayRange: "offense"` shows x in 0..47 with the hoop at x = 41.75
// (47 - 5.25). So:  surface_x = 41.75 - (coordinate_y - 1),  surface_y = coordinate_x - 25.
// sporty has no built-in ESPN basketball frame (its `nba-legacy` frame is for
// stats.nba.com LOC_X/LOC_Y, tenths of a foot); we pass the mapping as `from`.
//
// Sources: ESPN Site API v2 — site.api.espn.com/apis/site/v2/sports/basketball/nba/summary?event=401585607
// Offline fixture: test/fixtures/espn/summary_nba.json (ORL vs TOR, 2024-03-17).

import { mkdirSync, writeFileSync } from 'node:fs';
import sdv from 'sportsdataverse';
import { basketballCourt, toSurfaceFrame } from '@sportsdataverse/sporty';
import { toSVG } from '@sportsdataverse/sporty/svg';
import { teamColors } from '@sportsdataverse/sdvplot';
import { setup } from './_offline.mjs';
import { printTable, round } from './_util.mjs';

setup();

const EVENT_ID = 401585607;
const ESPN_NBA_FRAME = {
  x: (r) => (r.y == null || r.y < -100 ? null : 41.75 - (r.y - 1)),
  y: (r) => (r.x == null || r.x < -100 ? null : r.x - 25),
  description: 'ESPN basketball plays: x across (0-50, hoop 25), y from the hoop toward half court → sporty offense half',
};

const header = await sdv.nba.espnNbaSummary({ event_id: EVENT_ID, parsed: true, section: 'header' });
const competitors = JSON.parse(header[0].competitions)[0].competitors;
const teams = Object.fromEntries(competitors.map((c) => [c.team.id, c.team.abbreviation]));
const teamIds = Object.keys(teams);

const plays = await sdv.nba.espnNbaSummary({ event_id: EVENT_ID, parsed: true, section: 'plays' });
const shots = toSurfaceFrame(
  plays.filter((p) => p.shooting_play && p.coordinate_x > -100 && !/free throw/i.test(p.text)),
  { from: ESPN_NBA_FRAME, x: 'coordinate_x', y: 'coordinate_y' }
);

// Team colours resolve from sdvplot's bundled index (ESPN team ids work directly; no network).
const colors = await teamColors('nba', teamIds, { which: 'primary' });
const colorOf = Object.fromEntries(teamIds.map((id, i) => [id, colors[i]]));

printTable(
  shots.map((s) => ({ team: teams[s.team_id], made: s.scoring_play, x_espn: s.coordinate_x, y_espn: s.coordinate_y, surface_x: round(s.surface_x, 2), surface_y: s.surface_y, text: s.text })),
  ['team', 'made', 'x_espn', 'y_espn', 'surface_x', 'surface_y', 'text'],
  6,
  'Shots mapped onto the sporty court'
);

// Render: court SVG + one <circle> per shot inside the same y-flipped group.
const court = basketballCourt('nba', { displayRange: 'offense' });
const svg = toSVG(court, { width: 720 });
const marks = shots
  .map((s) => `<circle cx="${s.surface_x.toFixed(2)}" cy="${s.surface_y.toFixed(2)}" r="0.9" fill="${s.scoring_play ? colorOf[s.team_id] : 'none'}" stroke="${colorOf[s.team_id]}" stroke-width="0.25"/>`)
  .join('');
const out = svg.replace('</g></svg>', `${marks}</g></svg>`);

mkdirSync(new URL('./out/', import.meta.url), { recursive: true });
writeFileSync(new URL('./out/shot_chart.svg', import.meta.url), out);

printTable(
  teamIds.map((id) => ({ team: teams[id], color: colorOf[id], fga: shots.filter((s) => s.team_id === id).length, fgm: shots.filter((s) => s.team_id === id && s.scoring_play).length })),
  ['team', 'color', 'fga', 'fgm'],
  2,
  'Legend (filled = made, hollow = missed) → examples/out/shot_chart.svg'
);

91_sdvplot_standings_colors.mjs:
// 91 — Standings bar chart: ESPN WNBA standings → horizontal bars in team colours.
//
// Shows: @sportsdataverse/sdvplot `palette` (team → hex, keyed by whatever you
// passed — here ESPN team ids) and `logoUrl` (a CDN URL string, no fetch) laid
// out as a plain SVG. Written to examples/out/standings.svg. The packages are
// UNPUBLISHED (see README.md); colours come from sdvplot's bundled index, so
// this runs offline.
//
// Sources: ESPN Site API v2 — site.api.espn.com/apis/v2/sports/basketball/wnba/standings?season=2025
// Offline fixture: test/fixtures/espn/standings_wnba_2025.json (captured 2026-10-06).

import { mkdirSync, writeFileSync } from 'node:fs';
import sdv from 'sportsdataverse';
import { palette, logoUrl, onColor } from '@sportsdataverse/sdvplot';
import { setup } from './_offline.mjs';
import { printTable, round } from './_util.mjs';

setup();

const rows = (await sdv.wnba.espnWnbaStandings({ season: 2025, parsed: true })).sort((a, b) => b.win_percent - a.win_percent);
const ids = rows.map((r) => r.team_id);
const colors = await palette('wnba', ids);
const logos = Object.fromEntries(await Promise.all(ids.map(async (id) => [id, await logoUrl(id, 'wnba')])));

const table = rows.map((r) => ({ team: r.team_abbreviation, team_id: r.team_id, win_pct: round(r.win_percent, 3), color: colors[r.team_id], text_on: onColor(colors[r.team_id]), logo: logos[r.team_id] }));
printTable(table, ['team', 'team_id', 'win_pct', 'color', 'text_on', 'logo'], 6, 'Team colours + logo URLs resolved by ESPN id');

// Horizontal bar chart: one row per team, bar length = win%, logo at the left.
const ROW = 26;
const LEFT = 120;
const W = 640;
const H = 20 + rows.length * ROW;
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/"/g, '&quot;');
const bars = table
  .map((t, i) => {
    const y = 10 + i * ROW;
    const len = (W - LEFT - 60) * t.win_pct;
    return (
      `<image href="${esc(t.logo)}" x="4" y="${y + 2}" width="22" height="22"/>` +
      `<text x="32" y="${y + 17}" font-family="sans-serif" font-size="13">${esc(t.team)}</text>` +
      `<rect x="${LEFT}" y="${y + 3}" width="${len.toFixed(1)}" height="${ROW - 6}" fill="${t.color}" rx="3"/>` +
      `<text x="${LEFT + len + 6}" y="${y + 17}" font-family="sans-serif" font-size="12" fill="#333">${t.win_pct.toFixed(3)}</text>`
    );
  })
  .join('\n');
const svg = `<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" viewBox="0 0 ${W} ${H}" width="${W}" height="${H}">\n<rect width="${W}" height="${H}" fill="#fff"/>\n${bars}\n</svg>\n`;

mkdirSync(new URL('./out/', import.meta.url), { recursive: true });
writeFileSync(new URL('./out/standings.svg', import.meta.url), svg);
console.log(`wrote examples/out/standings.svg (${rows.length} bars)`);

92_sdvplot_roster_table.mjs:
// 92 — Roster table: ESPN NBA roster → an HTML table with headshots and the logo.
//
// Shows: @sportsdataverse/sdvplot `headshotUrl(playerId, league)` (ESPN ids by
// default) and `logoUrl` / `teamColors` to brand a plain HTML table. Written to
// examples/out/roster.html. URLs are strings — nothing is fetched, so this runs
// offline. The packages are UNPUBLISHED (see README.md).
//
// Sources: ESPN Site API v2 — site.api.espn.com/apis/site/v2/sports/basketball/nba/teams/13/roster
// Offline fixture: test/fixtures/espn/team_roster_nba.json (Lakers).

import { mkdirSync, writeFileSync } from 'node:fs';
import sdv from 'sportsdataverse';
import { headshotUrl, logoUrl, teamColors, onColor } from '@sportsdataverse/sdvplot';
import { setup } from './_offline.mjs';
import { printTable } from './_util.mjs';

setup();

const TEAM_ID = 13;
const roster = await sdv.nba.espnNbaTeamRoster({ team_id: TEAM_ID, parsed: true });
const [primary] = await teamColors('nba', [TEAM_ID], { which: 'primary' });
const logo = await logoUrl(TEAM_ID, 'nba');

const players = roster
  .map((p) => ({
    jersey: p.jersey,
    player: p.display_name,
    pos: p.position_abbreviation,
    height: p.display_height,
    weight: p.display_weight,
    age: p.age,
    exp: p.experience_years,
    headshot: headshotUrl(p.id, 'nba'),
  }))
  .sort((a, b) => Number(a.jersey) - Number(b.jersey));

printTable(players, ['jersey', 'player', 'pos', 'height', 'weight', 'age', 'exp', 'headshot'], 6, `Roster, team ${TEAM_ID} (headshotUrl from the ESPN athlete id)`);

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/"/g, '&quot;');
const html = `<!doctype html>
<meta charset="utf-8">
<title>Roster ${TEAM_ID}</title>
<style>
  body { font: 14px/1.4 system-ui, sans-serif; margin: 24px; }
  h1 { display: flex; align-items: center; gap: 12px; color: ${primary}; }
  h1 img { height: 48px; }
  table { border-collapse: collapse; }
  th { background: ${primary}; color: ${onColor(primary)}; text-align: left; padding: 6px 10px; }
  td { padding: 4px 10px; border-bottom: 1px solid #ddd; }
  td img { height: 40px; width: 40px; object-fit: cover; border-radius: 50%; background: #eee; }
</style>
<h1><img src="${esc(logo)}" alt=""> Team ${TEAM_ID} roster</h1>
<table>
<tr><th></th><th>#</th><th>Player</th><th>Pos</th><th>Ht</th><th>Wt</th><th>Age</th><th>Exp</th></tr>
${players.map((p) => `<tr><td><img src="${esc(p.headshot)}" alt=""></td><td>${esc(p.jersey)}</td><td>${esc(p.player)}</td><td>${esc(p.pos)}</td><td>${esc(p.height)}</td><td>${esc(p.weight)}</td><td>${esc(p.age)}</td><td>${esc(p.exp)}</td></tr>`).join('\n')}
</table>
`;

mkdirSync(new URL('./out/', import.meta.url), { recursive: true });
writeFileSync(new URL('./out/roster.html', import.meta.url), html);
console.log(`wrote examples/out/roster.html (${players.length} players, primary colour ${primary})`);

93_scores_card_action.mjs:
// 93 — Nightly scores card: one night's ESPN scoreboard → a team-coloured PNG, built to run in a GitHub Action.
//
// Shows: `espn<League>Scoreboard({ dates, parsed: true })` (one row per game) drawn as a
// plain SVG scores card with @sportsdataverse/sdvplot `palette` (team colours by ESPN id),
// `logoUrl` (archived logo URL) and `onColor` (black or white text on a colour), framed by
// `socialCard` (4:5 portrait) and rasterized by `toPNG` (optional peer @resvg/resvg-js,
// which downloads the logos with Node's fetch). Writes out/scores_card.png + scores_card.json
// next to this script.
//
// Inputs (env): LEAGUE = nba (default) | wnba | nfl | mlb | nhl | cfb | mbb | wbb
//               DATE   = YYYYMMDD or YYYY-MM-DD; default: yesterday in America/New_York
//               MAX    = most games on one card (default 16; a college Saturday has 50+)
// SDV_LIVE=1 hits the real hosts (ESPN + the logo CDN); the repo's docs build runs it
// offline against the committed fixture instead (examples/_offline.mjs, logos skipped).
// The workflow template is examples/workflows/scores-card.yml.
//
// Sources: ESPN Site API v2 — site.api.espn.com/apis/site/v2/sports/basketball/nba/scoreboard?dates=YYYYMMDD
// Offline fixture: test/fixtures/espn/scoreboard_nba.json (the night of 2024-12-01).

import { mkdirSync, writeFileSync } from 'node:fs';
import sdv from 'sportsdataverse';
import { logoUrl, mix, onColor, palette } from '@sportsdataverse/sdvplot';
import { socialCard, toPNG } from '@sportsdataverse/sdvplot/export';

const LIVE = process.env.SDV_LIVE === '1';
if (!LIVE) await import('./_offline.mjs').then((m) => m.setup()); // repo-only: serve committed fixtures

const LEAGUE = (process.env.LEAGUE || 'nba').toLowerCase();
const ET = 'America/New_York';
function yesterdayET() {
  const today = new Intl.DateTimeFormat('en-CA', { timeZone: ET }).format(new Date()); // YYYY-MM-DD
  const d = new Date(`${today}T12:00:00Z`);
  d.setUTCDate(d.getUTCDate() - 1);
  return d.toISOString().slice(0, 10).replaceAll('-', '');
}
const DATE = (process.env.DATE || yesterdayET()).replaceAll('-', '');
if (!/^\d{8}$/.test(DATE)) throw new Error(`DATE must be YYYYMMDD or YYYY-MM-DD, got ${process.env.DATE}`);

const scoreboard = sdv[LEAGUE]?.[`espn${LEAGUE[0].toUpperCase()}${LEAGUE.slice(1)}Scoreboard`];
if (!scoreboard) throw new Error(`no ESPN scoreboard for LEAGUE=${LEAGUE}`);
const all = (await scoreboard({ dates: DATE, parsed: true })).sort((a, b) => a.date.localeCompare(b.date));
const games = all.slice(0, Number(process.env.MAX) || 16);
if (games.length === 0) {
  console.log(`no ${LEAGUE.toUpperCase()} games on ${DATE}; nothing to draw`);
  process.exit(0);
}

// Colours and logos from sdvplot by ESPN team id; ESPN's own colour/logo fields are the fallback.
const ids = [...new Set(games.flatMap((g) => [g.away_id, g.home_id]))];
const colors = await palette(LEAGUE, ids, { idSystem: 'espn' });
const logos = Object.fromEntries(await Promise.all(ids.map(async (id) => [id, await logoUrl(id, LEAGUE, { idSystem: 'espn' })])));
const side = (g, s) => ({
  abbr: g[`${s}_abbreviation`],
  name: g[`${s}_name`],
  score: g.status_type_state === 'pre' ? '' : (g[`${s}_score`] ?? ''), // ESPN sends "0" before tip-off
  winner: g[`${s}_winner`] === true,
  color: colors[g[`${s}_id`]] ?? `#${g[`${s}_color`] || '777777'}`,
  logo: logos[g[`${s}_id`]] ?? g[`${s}_logo`],
});

// The night the games belong to, read from the data (first tip-off in Eastern time), not from DATE.
const night = new Intl.DateTimeFormat('en-US', { timeZone: ET, weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' }).format(new Date(games[0].date));

console.log(`## ${LEAGUE.toUpperCase()} scores, ${night}`);
console.log('| away | score | home | status | away colour | home colour |');
console.log('| --- | --- | --- | --- | --- | --- |');
for (const g of games) {
  const [a, h] = [side(g, 'away'), side(g, 'home')];
  console.log(`| ${a.abbr} | ${a.score}-${h.score} | ${h.abbr} | ${g.status_type_short_detail} | ${a.color} | ${h.color} |`);
}

// --- The card: a plain SVG, one tile per game, two rows per tile (away over home). ---
const FONT = "font-family=\"'DejaVu Sans', 'Liberation Sans', Arial, Helvetica, sans-serif\"";
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/"/g, '&quot;');
const W = 1000;
const COLS = games.length > 6 ? 2 : 1;
const GAP = 20;
const ROW = 56;
const TILE_W = (W - GAP * (COLS - 1)) / COLS;
const TILE_H = 30 + 2 * ROW + 8;
const TOP = 110;
const rowsOfTiles = Math.ceil(games.length / COLS);
const H = TOP + rowsOfTiles * (TILE_H + GAP) + 30;

// Text is not measured: widths are rough per-character estimates, generous enough for DejaVu Sans (wider than Arial).
const ABBR_W = Math.max(80, 19 * Math.max(...games.flatMap((g) => [g.away_abbreviation.length, g.home_abbreviation.length])) + 14);
const fit = (text, size, chars) => (String(text).length > chars ? Math.floor((size * chars) / String(text).length) : size);

function teamRow(t, x, y, loser) {
  const ink = loser ? '#6b6b6b' : '#111111';
  const weight = loser ? 400 : 700;
  const box = loser ? mix(t.color, '#ffffff', 0.55) : t.color; // the loser's score box fades toward white
  return (
    `<rect x="${x}" y="${y + 4}" width="10" height="${ROW - 8}" fill="${t.color}"/>` +
    (t.logo ? `<image href="${esc(t.logo)}" x="${x + 22}" y="${y + 6}" width="${ROW - 12}" height="${ROW - 12}"/>` : '') +
    `<text x="${x + ROW + 22}" y="${y + 37}" ${FONT} font-size="26" font-weight="${weight}" fill="${ink}">${esc(t.abbr)}</text>` +
    `<text x="${x + ROW + 22 + ABBR_W}" y="${y + 36}" ${FONT} font-size="${fit(t.name, 19, 16)}" fill="${ink}">${esc(t.name)}</text>` +
    `<rect x="${x + TILE_W - 96}" y="${y + 4}" width="88" height="${ROW - 8}" rx="6" fill="${box}"/>` +
    `<text x="${x + TILE_W - 52}" y="${y + 39}" ${FONT} font-size="30" font-weight="${weight}" text-anchor="middle" fill="${onColor(box)}">${esc(t.score)}</text>`
  );
}

const tiles = games.map((g, i) => {
  const x = (i % COLS) * (TILE_W + GAP);
  const y = TOP + Math.floor(i / COLS) * (TILE_H + GAP);
  const [a, h] = [side(g, 'away'), side(g, 'home')];
  const done = g.status_type_completed === true;
  const note = [g.status_type_short_detail, g.note].filter(Boolean).join(' · ');
  return (
    `<rect x="${x}" y="${y}" width="${TILE_W}" height="${TILE_H}" rx="10" fill="#ffffff" stroke="#d9d9d9"/>` +
    `<text x="${x + 22}" y="${y + 22}" ${FONT} font-size="15" fill="#555555">${esc(note)}</text>` +
    teamRow(a, x, y + 28, done && h.winner) +
    teamRow(h, x, y + 28 + ROW, done && a.winner)
  );
});

const svg =
  `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}">` +
  `<rect width="${W}" height="${H}" fill="#f4f4f4"/>` +
  `<text x="0" y="46" ${FONT} font-size="40" font-weight="700" fill="#111111">${LEAGUE.toUpperCase()} scores</text>` +
  `<text x="0" y="84" ${FONT} font-size="22" fill="#444444">${esc(night)}</text>` +
  tiles.join('') +
  `<text x="0" y="${H - 8}" ${FONT} font-size="15" fill="#666666">${all.length > games.length ? `First ${games.length} of ${all.length} games by start time · ` : ''}Data: ESPN via sportsdataverse · colours and logos: sdvplot</text>` +
  `</svg>`;

// 4:5 portrait card (1080 x 1350 at width 1080), the shape social feeds crop least.
const png = await toPNG(socialCard(svg, { aspect: '4:5', padding: 40, background: '#f4f4f4' }), {
  width: 1080,
  images: LIVE ? 'fetch' : 'skip',
});
const out = new URL('./out/', import.meta.url);
mkdirSync(out, { recursive: true });
writeFileSync(new URL('scores_card.png', out), png);
writeFileSync(
  new URL('scores_card.json', out),
  `${JSON.stringify({ league: LEAGUE, date: DATE, night, games: games.map((g) => ({ game_id: g.game_id, away: side(g, 'away'), home: side(g, 'home'), status: g.status_type_short_detail })) }, null, 2)}\n`
);
console.log(`\nwrote out/scores_card.png (${games.length} games, ${png.length} bytes) + out/scores_card.json`);

94_sdvplot_shots_vs_league.mjs:
// 94 — A game's shot chart against the league: ESPN plays + the 2023-24 league
// baseline → sdvplot hexagons coloured by FG% vs the league → PNG.
//
// Shows: ESPN summary `plays` for one game, mapped into the shot kit's frame
// (@sportsdataverse/sdvplot/shots: legacy tenths of a foot, hoop at the origin);
// `leagueIndex` over every 2023-24 field-goal attempt (the `espn_nba_shots`
// release, counted per ESPN spot in a committed snapshot); `cellsVsLeague` +
// `sizeCells` per team; `surface` + `shotCells` drawn with Observable Plot in
// Node (jsdom), then rasterised by `toPNG` (resvg). Writes
// examples/out/shots_vs_league.png. sdvplot-js is UNPUBLISHED (see README.md).
//
// Frame (fitted in 02_nba_pbp_shots.mjs, MAE 0.3 ft): ESPN `coordinate_x` is feet
// across the court with the hoop at 25, `coordinate_y` feet toward half court with
// the hoop at 1, whole feet, one basket for both teams. So
//   x_legacy = (coordinate_x - 25) * 10,  y_legacy = (coordinate_y - 1) * 10.
// Free throws carry a sentinel and are dropped. `shot_value` is ESPN's
// `points_attempted` (2 or 3); the shot kit reads it for the zones.
//
// The league snapshot: test/fixtures/releases/nba_shots_2024_spots.json, written by
// tools/snapshots/nba-league-shots.mjs from `sdv.nba.loadNbaShots({ seasons: 2024 })`
// (provenance inside the file). It includes this game: the release carries all
// 169 of its field-goal attempts, at the same spots as the summary below.
//
// Sources: ESPN Site API v2 — site.api.espn.com/apis/site/v2/sports/basketball/nba/summary?event=401585607
// and the sportsdataverse-data release espn_nba_shots/shots_2024.parquet.
// Offline fixtures: test/fixtures/espn/summary_nba.json (ORL vs TOR, 2024-03-17) + the snapshot above.

import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import * as Plot from '@observablehq/plot';
import { JSDOM } from 'jsdom';
import sdv from 'sportsdataverse';
import { teamColors } from '@sportsdataverse/sdvplot';
import { toPNG } from '@sportsdataverse/sdvplot/export';
import { shotCells, surface } from '@sportsdataverse/sdvplot/plot';
import { cellsVsLeague, diffScale, leagueIndex, sizeCells, statsByZone } from '@sportsdataverse/sdvplot/shots';
import { setup } from './_offline.mjs';
import { printTable, round } from './_util.mjs';

setup();

const EVENT_ID = 401585607;
const FONT = 'Arial, Helvetica, sans-serif'; // resvg draws text with the system's fonts; Plot's default system-ui resolves oddly there
const HEX = { radius: 20 }; // 2 ft hexagons: one game is ~85 attempts a team, so coarser than a season chart's 1.5 ft

/** One ESPN shot → the shot kit's ShotRow (legacy tenths, hoop at the origin). */
const shotRow = (x, y, value, made) => {
  const dx = x - 25;
  const dy = y - 1;
  return { x_legacy: dx * 10, y_legacy: dy * 10, shot_distance: Math.round(Math.hypot(dx, dy)), shot_value: value, shot_result: made ? 'Made' : 'Missed' };
};

// --- the game ------------------------------------------------------------------
const header = await sdv.nba.espnNbaSummary({ event_id: EVENT_ID, parsed: true, section: 'header' });
const competitors = JSON.parse(header[0].competitions)[0].competitors;
const teams = competitors.map((c) => ({ id: c.team.id, abbr: c.team.abbreviation, homeAway: c.homeAway, score: c.score }));

const plays = await sdv.nba.espnNbaSummary({ event_id: EVENT_ID, parsed: true, section: 'plays' });
const attempts = plays.filter((p) => p.shooting_play && p.coordinate_x > -100 && !/free throw/i.test(p.text));
// The join key: header team ids and play team ids must be the same type before we group on them.
const idTypes = new Set([...teams.map((t) => typeof t.id), ...attempts.map((p) => typeof p.team_id)]);
if (idTypes.size !== 1) throw new Error(`team_id types disagree between header and plays: ${[...idTypes]}`);

// --- the league ------------------------------------------------------------------
const snapshot = JSON.parse(readFileSync(new URL('../test/fixtures/releases/nba_shots_2024_spots.json', import.meta.url), 'utf8'));
const league = snapshot.spots.flatMap(([x, y, value, n, makes]) =>
  Array.from({ length: n }, (_, i) => shotRow(x, y, value, i < makes))
);
const index = leagueIndex(league, HEX);
const leagueZones = statsByZone(league);

// --- per team: cells vs league, zones vs league ---------------------------------------
const doc = new JSDOM('').window.document;
const court = surface('nba', { displayRange: 'defense', rotation: 90 });
const scale = diffScale();
const colors = await teamColors('nba', teams.map((t) => t.id), { which: 'primary' });
const zoneRows = [];
const panels = [];
const titles = [];
for (const [i, team] of teams.entries()) {
  const shots = attempts.filter((p) => p.team_id === team.id).map((p) => shotRow(p.coordinate_x, p.coordinate_y, p.points_attempted, p.scoring_play));
  const cells = cellsVsLeague(shots, index);
  const zones = statsByZone(shots);
  // corners merged: ESPN's left/right handedness against the legacy frame is not verified
  const merge = (z) => ({
    restricted_area: z.restricted_area,
    paint: z.paint,
    mid_range: z.mid_range,
    corner_3: { attempts: z.corner_3_left.attempts + z.corner_3_right.attempts, makes: z.corner_3_left.makes + z.corner_3_right.makes },
    above_break_3: z.above_break_3,
  });
  const lz = merge(leagueZones);
  for (const [zone, s] of Object.entries(merge(zones))) {
    const fg = s.attempts ? s.makes / s.attempts : null;
    const lfg = lz[zone].makes / lz[zone].attempts;
    zoneRows.push({ team: team.abbr, zone, fga: s.attempts, fgm: s.makes, fg_pct: round(fg, 3), league_fg_pct: round(lfg, 3), diff_pts: fg == null ? null : round((fg - lfg) * 100, 1) });
  }
  const fga = shots.length;
  const fgm = shots.filter((s) => s.shot_result === 'Made').length;
  titles.push({ text: `${team.abbr} ${fgm}/${fga} FG (${team.homeAway})`, color: colors[i] });
  panels.push(
    Plot.plot({
      ...court.scales,
      document: doc,
      style: { fontFamily: FONT },
      width: 360,
      marks: [
        ...court.marks,
        shotCells(cells, { r: sizeCells(cells, HEX).r, frame: 'nba-legacy-vertical', scale }),
      ],
    })
  );
}

// --- one PNG: the two courts side by side, a legend underneath ------------------------
const pts = (d) => (d === 0 ? '0' : `${d > 0 ? '+' : '−'}${Math.abs(d * 100).toFixed(0)}`);
// Plot.legend's continuous ramp paints a <canvas>, which jsdom lacks: draw the key as rects in the scale's colours.
const steps = Array.from({ length: 31 }, (_, i) => round(-0.15 + i * 0.01, 2));
const legend = Plot.plot({
  document: doc,
  style: { fontFamily: FONT },
  width: 360,
  height: 46,
  marginTop: 4,
  marginBottom: 30,
  x: { domain: [-0.155, 0.155], ticks: [-0.15, -0.1, -0.05, 0, 0.05, 0.1, 0.15], tickFormat: pts, label: 'FG% vs 2023-24 league, same hexagon (points) →', labelAnchor: 'center' },
  y: { axis: null },
  color: { type: 'identity' },
  marks: [Plot.rect(steps, { x1: (d) => d - 0.005, x2: (d) => d + 0.005, y1: 0, y2: 1, fill: (d) => scale(d) })],
});
const w = panels.map((p) => Number(p.getAttribute('width')));
const h = Math.max(...panels.map((p) => Number(p.getAttribute('height'))));
const W = w[0] + w[1] + 24;
const TOP = 36; // a title band above the courts
const H = TOP + h + 64;
const nested = (svg, x, y) => {
  svg.setAttribute('x', String(x));
  svg.setAttribute('y', String(y));
  return svg.outerHTML;
};
const svg =
  `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}" font-family="${FONT}">` +
  `<rect width="${W}" height="${H}" fill="white"/>` +
  titles.map((t, i) => `<text x="${i === 0 ? w[0] / 2 : w[0] + 24 + w[1] / 2}" y="26" text-anchor="middle" font-size="18" font-weight="bold" fill="${t.color}">${t.text}</text>`).join('') +
  nested(panels[0], 0, TOP) +
  nested(panels[1], w[0] + 24, TOP) +
  nested(legend, (W - 360) / 2, TOP + h + 8) +
  '</svg>';
mkdirSync(new URL('./out/', import.meta.url), { recursive: true });
writeFileSync(new URL('./out/shots_vs_league.png', import.meta.url), await toPNG(svg, { scale: 2 }));

printTable(
  teams.map((t, i) => ({ team: t.abbr, team_id: t.id, home_away: t.homeAway, score: t.score, color: colors[i] })),
  ['team', 'team_id', 'home_away', 'score', 'color'],
  2,
  `Game ${EVENT_ID} vs a league of ${snapshot.provenance.field_goal_attempts} attempts (${snapshot.provenance.games} games)`
);
printTable(zoneRows, ['team', 'zone', 'fga', 'fgm', 'fg_pct', 'league_fg_pct', 'diff_pts'], 10, 'FG% by zone against the league → examples/out/shots_vs_league.png');

95_rankings_ladder_action.mjs:
// 95 — Weekly power-rankings ladder: the AP Top 25 → a team-coloured ladder PNG, built for a weekly GitHub Action.
//
// Shows: `espnCfbCdnRankings()` parsed by `parseEndpoint('espn', 'cdn_rankings', raw)` (one row per
// poll entry, every poll), filtered
// to one poll and drawn as a 25-rung ladder: rank, movement since last week, logo, team,
// record, and a bar of poll points in the team's colour. Colours and logos come from
// @sportsdataverse/sdvplot `palette` / `logoUrl` by ESPN team id, bar labels from `onColor`;
// `socialCard` frames it 4:5 and `toPNG` (optional peer @resvg/resvg-js) rasterizes it,
// downloading the logos. Writes out/rankings_ladder.png + rankings_ladder.json next to this script.
//
// Inputs (env): POLL   = AP Top 25 (default) | AFCA Coaches Poll | …  (the `poll_name` column)
//               SEASON, WEEK = a past poll (regular season); default: ESPN's current week
// SDV_LIVE=1 hits the real hosts (ESPN + the logo CDN); the repo's docs build runs it
// offline against the committed fixture instead (examples/_offline.mjs, logos skipped).
// The workflow template is examples/workflows/rankings-ladder.yml.
//
// Sources: ESPN CDN — cdn.espn.com/core/college-football/rankings?xhr=1[&year=SEASON&week=WEEK]
// Offline fixture: test/fixtures/espn/cdn/rankings_cfb.json.gz (2024 week 5).

import { mkdirSync, writeFileSync } from 'node:fs';
import sdv from 'sportsdataverse';
import { parseEndpoint } from 'sportsdataverse/parsers';
import { logoUrl, onColor, palette } from '@sportsdataverse/sdvplot';
import { socialCard, toPNG } from '@sportsdataverse/sdvplot/export';

const LIVE = process.env.SDV_LIVE === '1';
if (!LIVE) await import('./_offline.mjs').then((m) => m.setup()); // repo-only: serve committed fixtures

const POLL = process.env.POLL || 'AP Top 25';
const args = {};
if (process.env.SEASON) args.season = Number(process.env.SEASON);
if (process.env.WEEK) Object.assign(args, { week: Number(process.env.WEEK), season_type: 2 });

// One request: keep the raw page (for the week label below) and parse it with the same parser `parsed: true` uses.
const raw = await sdv.cfb.espnCfbCdnRankings(args);
const parsed = parseEndpoint('espn', 'cdn_rankings', raw);
const ranked = parsed.filter((r) => r.poll_name === POLL && r.ranked === true).sort((a, b) => a.rank - b.rank);
if (ranked.length === 0) {
  // ESPN always serves some poll (the last one, off-season), so no rows means a wrong POLL or a changed payload: fail the run.
  console.error(`no "${POLL}" ranks for ${JSON.stringify(args)}; polls present: ${[...new Set(parsed.map((r) => r.poll_name))].join(' | ')}`);
  process.exit(1);
}

// The week ESPN actually served, from the page's own config (absent in the trimmed offline fixture).
const served = raw?.content?.config?.json?.requestedSeason;
const week = served ? `${served.year} ${served.week?.displayValue ?? ''}`.trim() : args.week ? `${args.season ?? ''} Week ${args.week}`.trim() : '';

const ids = ranked.map((r) => r.team_id);
const colors = await palette('cfb', ids, { idSystem: 'espn' });
const logos = Object.fromEntries(await Promise.all(ids.map(async (id) => [id, (await logoUrl(id, 'cfb', { idSystem: 'espn' })) ?? null])));
const rows = ranked.map((r) => ({
  rank: r.rank,
  // previous_rank 0 = unranked last week
  move: r.previous_rank > 0 ? r.previous_rank - r.rank : null,
  team: r.team_display_name,
  abbr: r.team_abbreviation,
  record: r.formatted_record,
  points: r.points,
  first: r.first_place_votes,
  color: colors[r.team_id] ?? '#777777',
  logo: logos[r.team_id] ?? r.team_logo,
}));

console.log(`## ${POLL}${week ? `, ${week}` : ''}`);
console.log('| rank | move | team | record | points | 1st | colour |');
console.log('| --- | --- | --- | --- | --- | --- | --- |');
for (const r of rows) {
  console.log(`| ${r.rank} | ${r.move === null ? 'new' : r.move} | ${r.team} | ${r.record} | ${r.points} | ${r.first || ''} | ${r.color} |`);
}

// --- The ladder: a plain SVG, one rung per team. ---
const FONT = "font-family=\"'DejaVu Sans', 'Liberation Sans', Arial, Helvetica, sans-serif\"";
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/"/g, '&quot;');
const W = 1000;
const RUNG = 44;
const TOP = 120;
const BAR_X = 470;
const BAR_W = W - BAR_X;
const H = TOP + rows.length * RUNG + 40;
const maxPoints = Math.max(...rows.map((r) => r.points || 0)) || 1;
// Text is not measured: a long team name shrinks to fit about 17 characters at 22 px (DejaVu Sans, the widest likely font).
const fit = (text, size, chars) => (String(text).length > chars ? Math.floor((size * chars) / String(text).length) : size);

function movement(m, x, y) {
  if (m === null) return `<text x="${x}" y="${y + 6}" ${FONT} font-size="13" font-weight="700" fill="#1f6feb">NEW</text>`;
  if (m === 0) return `<rect x="${x + 2}" y="${y - 1}" width="12" height="3" fill="#9a9a9a"/>`;
  const up = m > 0;
  const tri = up ? `${x},${y + 5} ${x + 14},${y + 5} ${x + 7},${y - 6}` : `${x},${y - 6} ${x + 14},${y - 6} ${x + 7},${y + 5}`;
  return `<polygon points="${tri}" fill="${up ? '#1a7f37' : '#cf222e'}"/><text x="${x + 18}" y="${y + 5}" ${FONT} font-size="15" fill="${up ? '#1a7f37' : '#cf222e'}">${Math.abs(m)}</text>`;
}

const rungs = rows.map((r, i) => {
  const y = TOP + i * RUNG;
  const mid = y + RUNG / 2;
  const len = Math.max(4, (BAR_W * (r.points || 0)) / maxPoints);
  const inside = len > 90;
  return (
    (i % 2 === 0 ? `<rect x="0" y="${y}" width="${W}" height="${RUNG}" fill="#f6f6f6"/>` : '') +
    `<text x="40" y="${mid + 9}" ${FONT} font-size="24" font-weight="700" text-anchor="end" fill="#111111">${r.rank}</text>` +
    movement(r.move, 54, mid) +
    (r.logo ? `<image href="${esc(r.logo)}" x="100" y="${y + 5}" width="${RUNG - 10}" height="${RUNG - 10}"/>` : '') +
    `<text x="146" y="${mid + 8}" ${FONT} font-size="${fit(r.team, 22, 17)}" font-weight="700" fill="#111111">${esc(r.team)}</text>` +
    `<text x="${BAR_X - 12}" y="${mid + 7}" ${FONT} font-size="17" text-anchor="end" fill="#555555">${esc(r.record)}${r.first ? ` (${r.first})` : ''}</text>` +
    `<rect x="${BAR_X}" y="${y + 7}" width="${len.toFixed(1)}" height="${RUNG - 14}" rx="4" fill="${r.color}" stroke="#00000022"/>` +
    `<text x="${inside ? BAR_X + len - 10 : BAR_X + len + 8}" y="${mid + 6}" ${FONT} font-size="16" text-anchor="${inside ? 'end' : 'start'}" fill="${inside ? onColor(r.color) : '#333333'}">${r.points}</text>`
  );
});

const svg =
  `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}">` +
  `<rect width="${W}" height="${H}" fill="#ffffff"/>` +
  `<text x="0" y="46" ${FONT} font-size="40" font-weight="700" fill="#111111">${esc(POLL)}</text>` +
  `<text x="0" y="84" ${FONT} font-size="22" fill="#444444">${esc(week || 'College football')} · bars are poll points, record (first-place votes)</text>` +
  rungs.join('') +
  `<text x="0" y="${H - 8}" ${FONT} font-size="15" fill="#666666">Data: ESPN via sportsdataverse · colours and logos: sdvplot</text>` +
  `</svg>`;

const png = await toPNG(socialCard(svg, { aspect: '4:5', padding: 40, background: '#ffffff' }), {
  width: 1080,
  images: LIVE ? 'fetch' : 'skip',
});
const out = new URL('./out/', import.meta.url);
mkdirSync(out, { recursive: true });
writeFileSync(new URL('rankings_ladder.png', out), png);
writeFileSync(new URL('rankings_ladder.json', out), `${JSON.stringify({ poll: POLL, week, rows }, null, 2)}\n`);
console.log(`\nwrote out/rankings_ladder.png (${rows.length} teams, ${png.length} bytes) + out/rankings_ladder.json`);

96_sdvplot_nfl_standings_table.mjs:
// 96 — Conference standings → a publication table PNG: ESPN NFL standings →
// @sportsdataverse/sdvtables → HTML → PNG (headless Chromium).
//
// Shows: `espnNflStandings({ season: 2024, parsed: true })` (one row per team),
// one `defineTable` spec per conference (team logo by ESPN id, record, win %,
// points, point differential, streak, a cutline under the 7th seed), the two set
// side by side by `gridTables`, and `htmlToPNG` from
// @sportsdataverse/sdvtables/export. Writes examples/out/nfl_standings_2024.png.
// sdvplot-js is UNPUBLISHED (see README.md); the PNG step also needs playwright and
// its browser (`npx playwright install chromium`) and loads the logos over the network.
//
// Sources: ESPN v2 standings — site.api.espn.com/apis/v2/sports/football/nfl/standings?season=2024
// Offline fixture: test/fixtures/espn/standings_nfl_2024.json (32 teams, final 2024 regular season).

import { mkdirSync, writeFileSync } from 'node:fs';
import sdv from 'sportsdataverse';
import { logoUrl } from '@sportsdataverse/sdvplot';
import { defineTable } from '@sportsdataverse/sdvtables';
import { gridTables, htmlToPNG } from '@sportsdataverse/sdvtables/export';
import { prepare } from '@sportsdataverse/sdvtables/html';
import { setup } from './_offline.mjs';
import { printTable, round } from './_util.mjs';

setup();

const standings = await sdv.nfl.espnNflStandings({ season: 2024, parsed: true });

// The logo column is keyed on the ESPN team id: check it is one type, and that sdvplot
// resolves each id to the same logo as the team's abbreviation (it does for all 32).
const idTypes = new Set(standings.map((r) => typeof r.team_id));
if (idTypes.size !== 1 || !idTypes.has('string')) throw new Error(`team_id is not one string type: ${[...idTypes]}`);
for (const r of standings) {
  if ((await logoUrl(r.team_id, 'nfl')) !== (await logoUrl(r.team_abbreviation, 'nfl'))) throw new Error(`logo for ${r.team_id} ≠ ${r.team_abbreviation}`);
}

const rows = standings
  .map((r) => ({
    conference: r.group_abbreviation,
    seed: r.playoff_seed,
    team_id: r.team_id,
    team: r.team_display_name,
    abbr: r.team_abbreviation,
    wins: r.wins,
    losses: r.losses,
    ties: r.ties,
    win_share: r.win_percent,
    pf: r.points_for,
    pa: r.points_against,
    diff: r.points_for - r.points_against,
    // ESPN's streak is signed: +4 = four straight wins, -1 = one loss
    streak: r.streak > 0 ? `W${r.streak}` : `L${-r.streak}`,
  }))
  .sort((a, b) => a.conference.localeCompare(b.conference) || a.seed - b.seed);

const tableFor = (conference) =>
  defineTable()
    .columns((c) => [
      c.int('seed', { label: '#' }),
      c.logo('team_id', { league: 'nfl', label: '', height: 24 }),
      c.text('team', { label: 'Team' }),
      c.int('wins', { label: 'W' }),
      c.int('losses', { label: 'L' }),
      c.pct('win_share', { label: 'Win %', decimals: 1 }),
      c.int('pf', { label: 'PF' }),
      c.int('pa', { label: 'PA' }),
      c.colorPills('diff', { label: 'Diff', domain: [-225, 225] }), // one domain, so AFC and NFC colours compare
      c.text('streak', { label: 'Streak' }),
    ])
    .cutline(7, { label: ['Playoff line'] })
    .theme('athletic')
    .title(conference)
    .build();

const afc = rows.filter((r) => r.conference === 'AFC');
const nfc = rows.filter((r) => r.conference === 'NFC');
const specs = [tableFor('AFC'), tableFor('NFC')];
await Promise.all(specs.map((s) => prepare(s))); // loads the NFL logo shard renderHTML reads
const html = gridTables(
  [
    { spec: specs[0], rows: afc },
    { spec: specs[1], rows: nfc },
  ],
  {
    ncol: 2,
    title: 'NFL standings, 2024 regular season',
    subtitle: 'By playoff seed; seeds 1-4 won their divisions, 5-7 are wild cards',
    sourceNote: 'Data: ESPN via sportsdataverse (sdv.nfl.espnNflStandings)',
  }
);
mkdirSync(new URL('./out/', import.meta.url), { recursive: true });
writeFileSync(new URL('./out/nfl_standings_2024.png', import.meta.url), await htmlToPNG(html, { width: 1200 }));

for (const [name, side] of [['AFC', afc], ['NFC', nfc]]) {
  printTable(
    side.map((r) => ({ seed: r.seed, team: r.abbr, team_id: r.team_id, record: `${r.wins}-${r.losses}${r.ties ? `-${r.ties}` : ''}`, win_pct: round(r.win_share, 3), pf: r.pf, pa: r.pa, diff: r.diff, streak: r.streak })),
    ['seed', 'team', 'team_id', 'record', 'win_pct', 'pf', 'pa', 'diff', 'streak'],
    16,
    `${name} by seed${name === 'NFC' ? ' → examples/out/nfl_standings_2024.png' : ''}`
  );
}

97_sdvplot_player_gamelog.mjs:
// 97 — A player's form: an ESPN game log → points per game with a rolling
// average, the season mean and the player's headshot → PNG.
//
// Shows: `espnNbaPlayerGamelog({ athlete_id: '1966', season: 2024 })` (LeBron
// James, 2023-24; ESPN web v3) taken RAW and joined by hand: the payload keeps the
// stat names (`names`), the per-game stats (`seasonTypes[].categories[].events[]`)
// and the game details (`events`, keyed by event id) in three places. Then the
// official regular season (ESPN files two games there that do not count), a
// 10-game rolling mean, and a chart drawn with Observable Plot in Node (jsdom):
// `teamColors` for the line, sdvplot's `meanLines` for the season average,
// `headshots` at the end of the line, `toPNG` (resvg, which downloads the
// headshot). Writes examples/out/lebron_2024_form.png. sdvplot-js is UNPUBLISHED.
//
// Sources: ESPN web v3 — site.web.api.espn.com/apis/common/v3/sports/basketball/nba/athletes/1966/gamelog?season=2024
// Offline fixture: test/fixtures/espn/athlete_gamelog_nba_1966_2024.json.gz (verbatim, captured 2026-10-08).

import { mkdirSync, writeFileSync } from 'node:fs';
import * as Plot from '@observablehq/plot';
import { JSDOM } from 'jsdom';
import sdv from 'sportsdataverse';
import { teamColors } from '@sportsdataverse/sdvplot';
import { toPNG } from '@sportsdataverse/sdvplot/export';
import { headshots, meanLines } from '@sportsdataverse/sdvplot/plot';
import { setup } from './_offline.mjs';
import { printTable, round } from './_util.mjs';

setup();

const ATHLETE_ID = '1966';
const WINDOW = 10;
const FONT = 'Arial, Helvetica, sans-serif'; // resvg draws text with the system's fonts; Plot's default system-ui resolves oddly there

const raw = await sdv.nba.espnNbaPlayerGamelog({ athlete_id: ATHLETE_ID, season: 2024 });

// --- join the three parts of the payload ---------------------------------------------
const col = Object.fromEntries(raw.names.map((n, i) => [n, i])); // 'points' → 13, …
const block = raw.seasonTypes.find((s) => / Regular Season$/.test(s.displayName) && !/Play In/.test(s.displayName));
const logged = block.categories.filter((c) => c.type === 'event').flatMap((c) => c.events);
// The join key: a game's eventId and the keys of `events` must agree in type (object keys are strings).
const keyTypes = new Set(logged.map((e) => typeof e.eventId));
if (keyTypes.size !== 1 || !keyTypes.has('string')) throw new Error(`eventId types: ${[...keyTypes]}`);
const games = logged.map((e) => {
  const g = raw.events[e.eventId];
  if (!g) throw new Error(`event ${e.eventId} has stats but no game details`);
  return {
    event_id: e.eventId,
    date: new Date(g.gameDate).toLocaleDateString('en-CA', { timeZone: 'America/New_York' }), // gameDate is UTC: an evening tip-off is the next day there
    opp: g.opponent.abbreviation,
    at_vs: g.atVs,
    result: g.gameResult,
    score: g.score,
    team_id: g.team.id,
    note: g.eventNote ?? '',
    min: Number(e.stats[col.minutes]),
    pts: Number(e.stats[col.points]),
    reb: Number(e.stats[col.totalRebounds]),
    ast: Number(e.stats[col.assists]),
  };
});

// ESPN's "Regular Season" block also holds the All-Star Game and the In-Season
// Tournament final, neither of which counts in the official season statistics.
const extra = games.filter((g) => /All-Star Game|In-Season Tournament Championship/.test(g.note));
const season = games.filter((g) => !extra.includes(g)).sort((a, b) => a.date.localeCompare(b.date));
season.forEach((g, i) => {
  g.game = i + 1;
  const win = season.slice(Math.max(0, i - WINDOW + 1), i + 1);
  g.pts_roll = win.length === WINDOW ? win.reduce((s, x) => s + x.pts, 0) / WINDOW : null;
});

const per = (k) => round(season.reduce((s, g) => s + g[k], 0) / season.length, 1);
const totals = { games: season.length, pts: season.reduce((s, g) => s + g.pts, 0), ppg: per('pts'), rpg: per('reb'), apg: per('ast'), mpg: per('min') };

// --- the chart -----------------------------------------------------------------------
const doc = new JSDOM('').window.document;
const teamIds = [...new Set(season.map((g) => g.team_id))];
if (teamIds.length !== 1) throw new Error(`more than one team in the season: ${teamIds}`);
const [lal] = await teamColors('nba', teamIds, { which: 'primary' });
const last = season.at(-1);
const peak = season.filter((g) => g.pts_roll != null).reduce((a, b) => (b.pts_roll > a.pts_roll ? b : a));
const chart = Plot.plot({
  document: doc,
  style: { fontFamily: FONT, background: 'white' },
  width: 820,
  height: 380,
  marginTop: 64,
  marginRight: 30,
  // no Plot `title`: it wraps the SVG in an HTML <figure>, and toPNG takes an SVG; the heading is a text mark
  x: { label: 'Game of the regular season →', domain: [0, season.length + 6] },
  y: { label: null, domain: [0, 45], grid: true },
  marks: [
    Plot.dot(season, { x: 'game', y: 'pts', r: 3.5, fill: (g) => (g.result === 'W' ? lal : 'white'), stroke: lal, strokeWidth: 1.2 }),
    Plot.line(season, { x: 'game', y: 'pts_roll', stroke: lal, strokeWidth: 3 }),
    ...meanLines(season, { y: 'pts', stroke: '#555', strokeDasharray: '5 4' }),
    Plot.text([totals.ppg], { x: 2, y: (d) => d, text: (d) => `season mean ${d}`, dy: -8, textAnchor: 'start', fill: '#555', stroke: 'white', strokeWidth: 4, fontSize: 12 }),
    Plot.text([peak], { x: 'game', y: 'pts_roll', text: (g) => `${WINDOW}-game high ${round(g.pts_roll, 1)}`, dy: -16, fill: lal, stroke: 'white', strokeWidth: 4, fontSize: 12, fontWeight: 'bold' }),
    Plot.text([{}], { frameAnchor: 'top-left', dy: -46, text: () => `LeBron James, 2023-24: points per game (${totals.games} games, ${totals.ppg} a game)`, fontSize: 16, fontWeight: 'bold', fill: '#111', textAnchor: 'start' }),
    Plot.text([{}], { frameAnchor: 'top-left', dy: -24, text: () => `● win  ○ loss  — ${WINDOW}-game rolling mean`, fontSize: 12, fill: '#333', textAnchor: 'start' }),
    headshots([last], { league: 'nba', player: () => ATHLETE_ID, x: () => season.length + 3.2, y: 'pts_roll', height: 0.2 }),
  ],
});
mkdirSync(new URL('./out/', import.meta.url), { recursive: true });
writeFileSync(new URL('./out/lebron_2024_form.png', import.meta.url), await toPNG(chart, { scale: 2 }));

printTable([totals], ['games', 'pts', 'ppg', 'rpg', 'apg', 'mpg'], 1, `Regular season (ESPN listed ${games.length} games; ${extra.length} do not count)`);
printTable(extra, ['date', 'opp', 'note', 'pts'], 2, 'Logged under Regular Season but not counted');
printTable(
  season.filter((g) => g.game % 10 === 0 || g === peak || g === last).map((g) => ({ ...g, pts_roll: round(g.pts_roll, 1) })),
  ['game', 'date', 'opp', 'at_vs', 'result', 'pts', 'pts_roll'],
  12,
  `Every 10th game, the peak and the last → examples/out/lebron_2024_form.png`
);

_util.mjs:
// Shared helpers for the example scripts. Deterministic output (no timestamps,
// no locale formatting) so tools/docs/inject-outputs.mjs can freeze the tables.

/**
 * Print the first `n` rows of `rows` as a markdown-ish table restricted to `cols`.
 * Plain pipes (not console.table's box drawing) so the output pastes into docs.
 */
export function printTable(rows, cols, n = 8, title) {
  if (title) console.log(`\n## ${title}`);
  const shown = (rows ?? []).slice(0, n);
  const fmt = (v) => {
    if (v == null) return '';
    if (typeof v === 'bigint') return `${v}n`;
    if (typeof v === 'number') return Number.isInteger(v) ? String(v) : String(Number(v.toFixed(3)));
    const s = typeof v === 'object' ? JSON.stringify(v) : String(v);
    return s.length > 28 ? `${s.slice(0, 25)}…` : s;
  };
  const widths = cols.map((c) => Math.max(c.length, ...shown.map((r) => fmt(r[c]).length)));
  const line = (cells) => `| ${cells.map((s, i) => s.padEnd(widths[i])).join(' | ')} |`;
  console.log(line(cols));
  console.log(line(widths.map((w) => '-'.repeat(w))));
  for (const r of shown) console.log(line(cols.map((c) => fmt(r[c]))));
  console.log(`(${rows?.length ?? 0} rows, ${n < (rows?.length ?? 0) ? `first ${n} shown` : 'all shown'})`);
}

/** Round to `d` decimals; keeps null/undefined. */
export const round = (v, d = 2) => (v == null ? v : Math.round(v * 10 ** d) / 10 ** d);
